#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""与 U-Boot 命令行交互（大核串口 /dev/ttyUSB0 @115200）。

用法：
  python3 uboot_cli.py "cmd1" "cmd2" ...     # 依次执行并打印输出
  python3 uboot_cli.py --raw 5               # 只读 5 秒
"""
import sys
import time

import serial

PORT = '/dev/ttyUSB0'
BAUD = 115200
PROMPT = b'=> '


def read_until(s, pats=(PROMPT,), timeout=20.0, echo=True):
    buf = b''
    end = time.time() + timeout
    while time.time() < end:
        d = s.read(4096)
        if d:
            buf += d
            for p in pats:
                if p in buf:
                    if echo:
                        sys.stdout.write(buf.decode('utf-8', 'replace'))
                        sys.stdout.flush()
                    return buf
        else:
            time.sleep(0.02)
    if echo:
        sys.stdout.write(buf.decode('utf-8', 'replace'))
        sys.stdout.flush()
    return buf


def main():
    s = serial.Serial(PORT, BAUD, timeout=0.2)
    s.reset_input_buffer()
    if sys.argv[1] == '--raw':
        end = time.time() + float(sys.argv[2])
        while time.time() < end:
            d = s.read(4096)
            if d:
                sys.stdout.write(d.decode('utf-8', 'replace'))
                sys.stdout.flush()
        s.close()
        return
    s.write(b'\r')
    read_until(s, timeout=8)
    for cmd in sys.argv[1:]:
        print('\n$ %s' % cmd)
        s.write(cmd.encode() + b'\r')
        read_until(s, timeout=40)
    s.close()


if __name__ == '__main__':
    main()

