rproc_virtio_create_vdev(unsigned int role, unsigned int notifyid,
			 void *rsc, struct metal_io_region *rsc_io,
			 void *priv,
			 rpvdev_notify_func notify,
			 virtio_dev_reset_cb rst_cb)
{
	struct remoteproc_virtio *rpvdev;
	struct virtio_vring_info *vrings_info;
	struct fw_rsc_vdev *vdev_rsc = rsc;
	struct virtio_device *vdev;
	unsigned int num_vrings = vdev_rsc->num_of_vrings;

	rpvdev = metal_allocate_memory(sizeof(*rpvdev));
	if (!rpvdev)
		return NULL;
	vrings_info = metal_allocate_memory(sizeof(*vrings_info) * num_vrings);
	if (!vrings_info)
		goto err;
	memset(rpvdev, 0, sizeof(*rpvdev));
	memset(vrings_info, 0, sizeof(*vrings_info) * num_vrings);

	/* Initialize the remoteproc virtio */
	rpvdev->notify = notify;
	rpvdev->priv = priv;
	/* Assuming the shared memory has been mapped and registered if
	 * necessary
	 */
	rpvdev->vdev_rsc = vdev_rsc;
	rpvdev->vdev_rsc_io = rsc_io;

	/* Initialize the virtio device */
	vdev = &rpvdev->vdev;
	vdev->vrings_info = vrings_info;
	vdev->notifyid = notifyid;
	vdev->id.device = vdev_rsc->id;
	vdev->role = role;
	vdev->reset_cb = rst_cb;
	vdev->vrings_num = num_vrings;
	vdev->func = &remoteproc_virtio_dispatch_funcs;

#if VIRTIO_ENABLED(VIRTIO_DRIVER_SUPPORT)
	if (role == VIRTIO_DEV_DRIVER) {
		uint32_t dfeatures = rproc_virtio_get_dfeatures(vdev);
		/* Assume the virtio driver support all remote features */
		rproc_virtio_negotiate_features(vdev, dfeatures);
	}
#endif

	return &rpvdev->vdev;
err:
	metal_free_memory(rpvdev);
	return NULL;
}

/**
 * @brief Get the virtio device features.
 *
 * @param vdev		Pointer to device structure.
 * @param features	Pointer to features supported by both the driver and
 *			the device as a bitfield.
 *
 * @return 0 on success, otherwise error code.
 */
static inline int virtio_get_features(struct virtio_device *vdev,
				      uint64_t *features)
{
	int ret = -EINVAL;

	if (vdev && features) {
		if (vdev->func && vdev->func->get_features) {
			*features = vdev->func->get_features(vdev);
			if (VIRTIO_ROLE_IS_DEVICE(vdev))
				vdev->features = *features;
			ret = 0;
		} else
			ret = -ENXIO;
	}

	return ret;
}

