static void vq_ring_init(struct virtqueue *vq, void *ring_mem, size_t alignment)
{
	struct vring *vr;
	uint16_t size;

	size = vq->vq_nentries;
	vr = &vq->vq_ring;

	vring_init(vr, size, ring_mem, alignment);

	if (VIRTIO_ROLE_IS_DRIVER(vq->vq_dev)) {
		struct vring_desc *desc = vr->desc;
		uint16_t i;

		for (i = 0U; i < size - 1U; i++)
			desc[i].next = i + 1U;
		desc[i].next = VQ_RING_DESC_CHAIN_END;
	}
}

