       * 统一给最高 level=7；不区分源（曾试过 UART 高/timer 低分级，
       * 对丢字符无效且已撤销）。 */

      k1r_eclic_set_intctl(eclic, g_max_level, 0);
      K1R_ECLIC_CTRL(eclic)->intie = 1;
