int k1_rptun_init(const char *peername)
{
  struct k1_rptun_dev_s *dev = &g_rptun_dev;
  int ret;

  memset(dev, 0, sizeof(*dev));

#ifdef CONFIG_K1R_RPTUN_MASTER
  dev->master = true;
#else
  dev->master = false;   /* RCPU 是 remote (AP 为 master) */
#endif

  /* rptun addrenv: **pa 是 AP 视角的物理地址，da 是 RCPU 视角的窗口地址**。
   * rptun 框架用它在两者之间换算（rptun_pa_to_da / rptun_da_to_pa）。 */

  dev->addrenv[0].pa   = K1R_VRING0_PA;
  dev->addrenv[0].da   = K1R_VRING0_DA;
  dev->addrenv[0].size = K1R_VRING_SZ;
  dev->addrenv[1].pa   = K1R_VRING1_PA;
  dev->addrenv[1].da   = K1R_VRING1_DA;
  dev->addrenv[1].size = K1R_VRING_SZ;
  dev->addrenv[2].pa   = K1R_VDEV_BUF_PA;
  dev->addrenv[2].da   = K1R_VDEV_BUF_DA;
  dev->addrenv[2].size = K1R_VDEV_BUF_SZ;
  dev->addrenv[3].pa   = K1R_SHM_BUF_PA;
  dev->addrenv[3].da   = K1R_SHM_BUF_DA;
  dev->addrenv[3].size = K1R_SHM_BUF_SZ;
  dev->addrenv[4].size = 0;   /* 终止 */

  /* 同样的映射也要登记给 libmetal/驱动层用（up_addrenv_pa_to_va/va_to_pa）。
   * 描述符里存的是 AP 的物理地址，不转换就会被当指针直接访问 → Store access fault。 */

#ifdef CONFIG_DEV_SIMPLE_ADDRENV
  simple_addrenv_initialize(g_k1r_shm_addrenv);
  k1rinfo("k1r rptun: shm addrenv pa 0x%lx/0x%lx/0x%lx -> da 0x%lx/0x%lx/0x%lx\n",
          (unsigned long)K1R_VRING0_PA, (unsigned long)K1R_VRING1_PA,
          (unsigned long)K1R_VDEV_BUF_PA, (unsigned long)K1R_VRING0_DA,
          (unsigned long)K1R_VRING1_DA, (unsigned long)K1R_VDEV_BUF_DA);
#endif

  ret = irq_attach(K1R_MAILBOX_IRQ, k1r_mailbox_irq, NULL);
  if (ret < 0)
    {
      k1rinfo("k1r rptun: mailbox irq_attach(%d) failed %d\n",
              K1R_MAILBOX_IRQ, ret);
      return ret;
    }

  up_enable_irq(K1R_MAILBOX_IRQ);

  dev->rptun.ops = &g_k1_rptun_ops;
  strncpy(dev->peername, peername, sizeof(dev->peername) - 1);

  ret = rptun_initialize(&dev->rptun);
  if (ret < 0)
    {
      k1rinfo("k1r rptun: rptun_initialize failed %d\n", ret);
      up_disable_irq(K1R_MAILBOX_IRQ);
      return ret;
    }

  k1rinfo("k1r rptun: init ok peer=%s master=%d irq=%d\n",
          dev->peername, dev->master ? 1 : 0, K1R_MAILBOX_IRQ);

  return OK;
}

