static int k1r_mailbox_irq(int irq, void *context, void *arg)
{
  struct k1_rptun_dev_s *priv = &g_rptun_dev;
  volatile uint32_t *iir  = (volatile uint32_t *)(K1R_MAILBOX_BASE + K1R_MBOX_IIR);
  volatile uint32_t *isrw = (volatile uint32_t *)(K1R_MAILBOX_BASE + K1R_MBOX_ISRW);
  uint32_t status;
  int i;

  UNUSED(irq);
  UNUSED(context);
  UNUSED(arg);

  /* 与 AP/esOS k1x-mailbox 完全一致：必须先写 0 锁存当前中断快照，再读。
   * 直接读 ipc_iir 会拿到 0/脏值 → 既不清 icr 也不回 ack → 邮箱中断线不撤销
   * → ECLIC 电平中断反复触发 → RCPU 卡死在中断风暴里（看不到 "init ok"）。 */

  *iir = 0;
  status = *iir;

  /* 先处理 tx-ack 区 (bit 4-7)：AP 对我们 kick 的确认，只需清 icr，无需再 ack */

  for (i = 0; i < K1R_MAILBOX_CHAN_MAX; i++)
    {
      if (status & (1UL << (i + 4)))
        {
          k1r_mailbox_clear(i + 4);
        }
    }

  /* 再处理新消息区 (bit 0-3)：AP -> RCPU 的 kick，清 icr 并回 ack(isrw bit(i+4)) */

  for (i = 0; i < K1R_MAILBOX_CHAN_MAX; i++)
    {
      if (status & (1UL << i))
        {
          k1r_mailbox_clear(i);
          *isrw = (1UL << (i + 4));
        }
    }

  if (priv->callback)
    {
      priv->callback(priv->arg, RPTUN_NOTIFY_ALL);
    }

  return OK;

